function within(o,days){return Date.now()-o.at<=days*864e5}
function agg(days){var os=S.orders.filter(function(o){return !o.cancelled&&within(o,days)}),gross=0,disc=0,ref=0,tax=0,ship=0;os.forEach(function(o){gross+=o.sub;disc+=o.disc||0;ref+=o.refunded||0;tax+=o.tax||0;ship+=o.shipAmt||0});var net=gross-disc-ref,sess=Math.max(S.stats.views||0,0);return{os:os,n:os.length,gross:r2(gross),disc:r2(disc),ref:r2(ref),tax:r2(tax),ship:r2(ship),net:r2(net),total:r2(net+tax+ship),aov:os.length?r2((gross-disc)/os.length):0,sess:sess,conv:sess?r2(os.length/sess*100):0}}
X.agg=agg;
function series(days){var b=[];for(var i=days-1;i>=0;i--){var d0=new Date();d0.setHours(0,0,0,0);var s=d0.getTime()-i*864e5;b.push({d:new Date(s),v:S.orders.filter(function(o){return !o.cancelled&&o.at>=s&&o.at<s+864e5}).reduce(function(a,o){return a+o.total-o.refunded},0)})}return b}
function bars(b){var mx=Math.max.apply(null,b.map(function(x){return x.v}).concat([1]));return '<div class="xbar">'+b.map(function(x){return '<i title="'+x.d.toLocaleDateString()+': '+money(x.v)+'" style="height:'+(x.v/mx*100)+'%"></i>'}).join('')+'</div>'}
V.analytics=function(){var a=agg(30);var top={};a.os.forEach(function(o){o.items.forEach(function(l){top[l.name]=(top[l.name]||0)+l.q*l.price})});
 return '<div class="xw">'+head('Analytics','<span class="xk">Last 30 days · computed from your orders</span><button class="btn" data-x="go:analytics-reports">Reports</button>')+'<div class="xg">'+[['Total sales',money(a.total)],['Orders',a.n],['Average order value',money(a.aov)],['Online store sessions',a.sess],['Conversion rate',a.conv+'%'],['Returns',money(a.ref)]].map(function(k){return '<div class="xc"><div class="xk">'+k[0]+'</div><div class="xb">'+k[1]+'</div></div>'}).join('')+'</div><div class="xc"><h3>Sales over time</h3>'+bars(series(30))+'</div><div class="xc"><h3>Top products</h3><table class="xt">'+Object.keys(top).sort(function(x,y){return top[y]-top[x]}).slice(0,8).map(function(k){return '<tr><td>'+h(k)+'</td><td>'+money(top[k])+'</td></tr>'}).join('')+'</table></div></div>'};
